// ratelimiter/ratelimiter.go
package ratelimiter

import (
	"fmt"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	capacity float64
	rate     float64 // tokens per second
	last     time.Time
	clock    Clock
}

// NewLimiter creates a Limiter with the given bucket capacity and refill
// rate (tokens/sec). It returns an error if capacity or rate is non-positive
// or clock is nil.
func NewLimiter(capacity int, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, fmt.Errorf("ratelimiter: capacity must be > 0, got %d", capacity)
	}
	if rate <= 0 {
		return nil, fmt.Errorf("ratelimiter: rate must be > 0, got %v", rate)
	}
	if clock == nil {
		return nil, fmt.Errorf("ratelimiter: clock must not be nil")
	}
	return &Limiter{
		tokens:   float64(capacity),
		capacity: float64(capacity),
		rate:     rate,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// AllowN reports whether n tokens can be consumed. If so, it consumes them
// and returns true; otherwise it returns false without consuming.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.last = now
	}

	if l.tokens >= float64(n) {
		l.tokens -= float64(n)
		return true
	}
	return false
}
